// ============================================================================
// DIMENSION: query / fragment transform + rendering
// Verified black-box: 13,298 byte-exact whole-stdout predictions, 0 failures,
// plus ~70 hand-inspected cases (od byte dumps). Nothing below is inferred.
// argv mapping: argv[5] = query, argv[6] = fragment (0-indexed argv[4], argv[5]).
// ============================================================================

// ---------------------------------------------------------------------------
// 0. DELIVERY LAYER (operating system, NOT the library) - model this first
// ---------------------------------------------------------------------------
// (a) argv entries are NUL-terminated C strings. The value the library receives
//     is the byte prefix up to the first 0x00.
//       exec(BIN,"http","e","80","/","a\0b","c\0d")
//         -> L5=[a] L6=[c] L7=[http://e:80/?a#c] L8=1
// (b) Each argv entry must be <= 131071 bytes (Linux MAX_ARG_STRLEN = 131072
//     including the NUL). At 131072+ execve fails E2BIG and the program never
//     runs (rc=127, zero bytes of stdout). This is NOT a library cap.
//       131071 'z' as query -> rc=0, L5_len=131071, L7_len=131086, L8=1
//       131072 'z' as query -> "Argument list too long", no output
//
// So, for the library itself: query and fragment are arbitrary byte strings of
// length 0 .. 131071 over the alphabet 0x01..0xFF. Every such value is legal.

// ---------------------------------------------------------------------------
// 1. STORAGE: pure identity. No transformation of any kind.
// ---------------------------------------------------------------------------
fn from_components(scheme, host, port, path, query, fragment) -> Url {
    // ... scheme/host/port/path handled by other dimensions ...
    url.query    = query;      // EXACT bytes. memcpy semantics.
    url.fragment = fragment;   // EXACT bytes. memcpy semantics.
    // The following are all explicitly NOT performed (each disproven by test):
    //   * strip leading '?' from query / leading '#' from fragment
    //   * trim leading, trailing, or interior whitespace
    //   * lowercase / uppercase / any case folding
    //   * percent-ENCODE unsafe bytes (space, '#', '?', '/', '%', ... stay raw)
    //   * percent-DECODE existing escapes ("%20" stays "%20", "%41" stays "%41")
    //   * normalize %XX hex case ("%2f" and "%2F" both survive unchanged)
    //   * repair malformed escapes ("%", "%2", "%zz" survive unchanged)
    //   * convert '+' <-> ' ' either direction
    //   * call normalize_query(): no key sorting, no dedupe, no merging,
    //     no dropping of empty pairs, no ';'/'&' unification
    //   * split a '#' out of query into fragment
    //   * split a '?' out of fragment into query
    //   * truncate at any length
    //   * strip/replace control bytes or invalid UTF-8
}
fn query(&self)    -> &[u8] { &self.query }     // printed verbatim as line 5
fn fragment(&self) -> &[u8] { &self.fragment }  // printed verbatim as line 6

// ---------------------------------------------------------------------------
// 2. RENDERING (to_string, line 7)
// ---------------------------------------------------------------------------
fn to_string(&self) -> String {
    let mut s = render_scheme_authority_path();   // other dimensions; may be ""
    if self.query.len()    != 0 { s.push(b'?'); s.extend(&self.query);    }
    if self.fragment.len() != 0 { s.push(b'#'); s.extend(&self.fragment); }
    s
}
// * The emptiness test is byte-length == 0 and NOTHING else. A single space is
//   non-empty and DOES emit its separator: q=" " f=" " -> od shows '/ ? sp # sp'.
// * Separators are appended raw, in fixed order (base, ?query, #fragment).
//   Fragment never precedes query. Never more than one separator is ADDED.
// * No escaping happens at render time, so to_string is NOT round-trippable.
// * There is NO guard for an empty base: an empty prefix still gets separators.
// * Exact length identity (verified at 44 lengths, 0..131071):
//     len(L7) == len(base) + (q.len()? 1+q.len() : 0) + (f.len()? 1+f.len() : 0)

// ---------------------------------------------------------------------------
// 3. VALIDITY (line 8)
// ---------------------------------------------------------------------------
fn is_valid(&self) -> bool { /* function of scheme/host/port/path ONLY */ }
// query and fragment contribute ZERO bits. They never invalidate a valid URL
// and never rescue an invalid one. Asserted on all 13,298 checks, which
// included the invalid shapes ("","","0",""), ("","","-1",""),
// ("http","","-1",""), ("http","","0","") crossed with all 255 byte values.
// Likewise lines 1-4 are byte-identical to the q=f="" run in every case.

// ---------------------------------------------------------------------------
// 4. EXACT LITERAL OUTPUTS FOR THE SURPRISING CASES (copy these into tests)
// ---------------------------------------------------------------------------
// args (scheme, host, port, path, query, fragment)  ->  line 7  [line 8]
//
//  leading separators are KEPT, producing doubles:
//   ("http","example.com","80","/","?q=1","")   -> "http://example.com:80/??q=1"   [1]
//   ("http","example.com","80","/","?","#")     -> "http://example.com:80/??##"    [1]
//   ("http","example.com","80","/","??","##")   -> "http://example.com:80/???###"  [1]
//   ("http","example.com","80","/","#","#")     -> "http://example.com:80/?###"    [1]
//   ("http","example.com","80","/","?#","#?")   -> "http://example.com:80/??###?"  [1]
//   ("http","example.com","80","/","&","&")     -> "http://example.com:80/?&#&"    [1]
//   ("http","example.com","80","/","=","=")     -> "http://example.com:80/?=#="    [1]
//
//  '#' in query does not become the fragment (both coexist):
//   ("http","example.com","80","/","q=1#frag","myfrag")
//        -> "http://example.com:80/?q=1#frag#myfrag"  L5="q=1#frag" L6="myfrag" [1]
//   ("http","example.com","80","/","a#b#c","d#e") -> "http://example.com:80/?a#b#c#d#e" [1]
//  '?' in fragment does not become the query:
//   ("http","example.com","80","/","q=1","?x=2") -> "http://example.com:80/?q=1#?x=2" [1]
//
//  no normalization of pairs:
//   ("http","example.com","80","/","b=2&a=1","")  -> "http://example.com:80/?b=2&a=1"  [1]
//   ("http","example.com","80","/","a=1&&b=2","") -> "http://example.com:80/?a=1&&b=2" [1]
//   ("http","example.com","80","/","%2f%2F","")   -> "http://example.com:80/?%2f%2F"   [1]
//   ("http","example.com","80","/","q=a b","")    -> "http://example.com:80/?q=a b"    [1]
//   ("http","example.com","80","/","q=%zz&r=%&s=%2","%zz%")
//        -> "http://example.com:80/?q=%zz&r=%&s=%2#%zz%"                              [1]
//
//  empty / elided prefix still gets separators:
//   ("","","0","","Q","F")            -> "?Q#F"   [0]
//   ("","","0","","","F")             -> "#F"     [0]
//   ("","","0","","Q","")             -> "?Q"     [0]
//   ("","example.com","-1","","","")  -> ""       [1]   <- valid, empty to_string
//   ("","example.com","-1","","Q","F")-> "?Q#F"   [1]
//   ("","","-1","","?q=1","#f")       -> "??q=1##f" [0]
//   ("http","example.com","80","","?q=1","") -> "http://example.com:80??q=1" [1]
//
//  separators are appended after whatever path renders (path may itself hold
//  '?'/'#', and path() prepends '/' - a path-dimension effect):
//   ("http","example.com","80","/a?b","c=d","e") -> "http://example.com:80/a?b?c=d#e" [1]
//   ("http","example.com","80","/a#b","c=d","e") -> "http://example.com:80/a#b?c=d#e" [1]
//   ("http","example.com","80","?","q","f")  L4="/?" -> "http://example.com:80/??q#f" [1]
//   ("http","example.com","80","#","q","f")  L4="/#" -> "http://example.com:80/#?q#f" [1]
//
//  raw bytes pass through (od-verified):
//   q="a\tb" f="c\td" -> line7 bytes: ...":80/ ? a \t b # c \t d"
//   q="a\nb" f="c\nd" -> ...":80/ ? a \n b # c \n d"   (stdout becomes 10 lines!)
//   q="\x7f" f="\x0b\x0c" -> ...":80/ ? 177 # \v \f"
//   q="q=\xff\xfe" f="\x80f" -> ...":80/ ? q = 377 376 # 200 f"
//
// ---------------------------------------------------------------------------
// 5. NOT THIS DIMENSION, but a harness must handle it
// ---------------------------------------------------------------------------
// * A port string std::stoi cannot parse (e.g. "abc") aborts BEFORE any output:
//   rc=134, stdout empty, stderr "terminate called after throwing an instance
//   of 'std::invalid_argument' / what(): stoi". Independent of query/fragment.
// * 5 argv values -> rc=1 and completely silent; 7 -> extra ignored, normal
//   output. A dropped trailing empty argument therefore fails silently.
// * A query or fragment containing 0x0A makes the 8-line stdout format
//   ambiguous to line-based parsers; parse by expected field or use byte
//   offsets, since the bytes themselves are stored and emitted verbatim.

// ============================================================
// DIMENSION: is_valid-predicate  -- definitive spec after falsification
// Binary: /workspace/dataset/test15_executable
// Contract: argv = [scheme, host, port, path, query, fragment]
// ============================================================

fn main(args: Vec<String>) -> ! {
    // --- STEP 0: argc gate (observed, out of the stated contract) ---
    // Fewer than 6 user args -> exit(1) with EMPTY stdout and EMPTY stderr.
    //   evidence: 0,1,2,3,4,5 args -> rc=1, out=[]
    // More than 6 -> extra args ignored entirely.
    //   evidence: ("http","example.com","80","/","","","EXTRA0") -> same 8 lines, last=1
    if args.len() < 6 { exit(1); }
    let (scheme_in, host_in, port_in, path_in, query_in, frag_in) =
        (args[0], args[1], args[2], args[3], args[4], args[5]);

    // --- STEP 1: port parse. THIS RUNS BEFORE ANY OUTPUT. ---
    // Semantics of C++ std::stoi on the raw bytes:
    //   skip leading isspace(): ' ' \t \n \v \f \r
    //   optional single '+' or '-' IMMEDIATELY before the first digit
    //   consume ASCII decimal digits [0-9]+ (non-ASCII digits do NOT count)
    //   ignore all trailing bytes
    // If zero digits were consumed -> std::invalid_argument
    // If the value does not fit in i32 -> std::out_of_range
    // Either exception is UNCAUGHT: process aborts.
    //   observable: stdout is EXACTLY 0 bytes, exit code 134 (SIGABRT, core dumped),
    //   stderr = "terminate called after throwing an instance of 'std::invalid_argument'\n  what():  stoi"
    //            (or 'std::out_of_range' for overflow)
    //   THERE IS NO is_valid OUTPUT IN THIS CASE. It is not a validity-0 path.
    // Aborting examples (verified against all 4 host/path combos):
    //   "", " ", "  ", "abc", "abc80", "+", "-", "++80", "+-80", "-+80", ".5",
    //   "INF", "inf", "nan", "NaN", "-  80", "\u{663}", "\u{FF12}", "\u{1D7D6}",
    //   "2147483648", "-2147483649"
    // Parsing examples: "80abc"->80, "080"->80, "00"->0, "-0"->0, "0x50"->0,
    //   "0X50"->0, "1e3"->1, "3.14"->3, "1,000"->1, "1 2"->1, "1_0"->1,
    //   " 80"->80, "\t80"->80, "\n80"->80, "\v80"->80, "\f80"->80, "\r80"->80,
    //   "80 "->80, "80\v"->80, "  -80"->-80, "2147483647"->2147483647,
    //   "-2147483648"->-2147483648
    let n: i32 = stoi_or_abort(port_in);

    // --- STEP 2: field storage (side effects; none of these change validity) ---
    let scheme = ascii_lowercase(scheme_in);   // byte-wise: 'A'..='Z' -> +32; ALL other bytes
                                               // untouched. NOT locale-aware: LC_ALL=tr_TR.UTF-8
                                               // still maps "HTTPI"->"httpi". "CAF\xC3\x89" -> "caf\xC3\x89".
    let host = host_in;                        // stored VERBATIM: no trim, no case fold, no validation.
    let port = if n >= 0 && n <= 65535 { n } else { -1 };  // 65535 kept; 65536 -> -1; any negative -> -1
    let path = if path_in.is_empty() { "".to_string() }
               else if path_in.starts_with('/') { path_in }
               else { format!("/{}", path_in) };
    let query = query_in;                      // verbatim
    let fragment = frag_in;                    // verbatim

    // --- STEP 3: THE PREDICATE (the whole dimension) ---
    // is_valid() == !host.is_empty() || !path.is_empty()
    // Equivalently: !(host.is_empty() && path.is_empty())
    //               host.len() + path.len() > 0
    // "empty" means ZERO BYTES. Nothing else counts:
    //   - no trimming: host " " / "\t" / "\n" / 0x01 / 0x7F  => VALID
    //   - no charset/DNS/IP/length check: every one of the 255 non-NUL byte values,
    //     invalid UTF-8 (0xFF, 0xC0 0x80), 131071-byte hosts => VALID
    //   - scheme is IGNORED (including "file", "mailto", "data", "about", "javascript")
    //   - port is IGNORED (including 0, -1, 65536, and clamped-to--1 values)
    //   - query and fragment are IGNORED (including 10000-byte ones)
    // Because a non-empty argv host/path can never normalize to empty, computing this
    // on the raw argv values or on the stored values is provably identical.
    let is_valid = !host.is_empty() || !path.is_empty();

    // --- STEP 4: output, 8 println!'s in this exact order ---
    // 1 scheme(), 2 host(), 3 port() as decimal i32, 4 path(), 5 query(),
    // 6 fragment(), 7 to_string(), 8 is_valid() printed as "1" or "0"
    //   (integer form, NOT "true"/"false"; std::boolalpha is not used)
    // CAUTION for test harnesses: if any field contains LF the output has MORE than
    // 8 lines; is_valid is always the LAST line.
    //   ("http","a\nb","80","","","") -> 10 lines, last = "1"
    exit(0);
}

// ============================================================
// GOLDEN CASES (exact literals; all re-run and verified)
// ============================================================
// ("http","example.com","80","/","","")  -> http|example.com|80|/|||http://example.com:80/|1
// ("http","example.com","-1","","","")   -> http|example.com|-1||||http://example.com|1
// ("http","example.com","0","/","","")   -> ...|http://example.com:0/|1
// ("http","","80","/","","")             -> http||80|/|||http://:80/|1
// ("http","","80","","","")              -> http||80||||http://:80|0     <-- non-empty to_string, INVALID
// ("http","","-1","","","")              -> http||-1||||http://|0
// ("http","","80","","qqq","fff")        -> http||80||qqq|fff|http://:80?qqq#fff|0
// ("","example.com","80","/","","")      -> |example.com|80|/|||/|1       <-- authority vanishes, valid
// ("","a","80","","","")                 -> |a|80|||||1                  <-- EMPTY to_string, VALID
// ("","a","80","","q","f")               -> |a|80||q|f|?q#f|1
// ("","","0","","","")                   -> ||0|||||0
// ("",""," 80"," ","","")  [path=space]  -> ||80|/ |||/ |1
// ("",""," 80","","","")   [all empty]   -> ||80|||||0
// ("file","","80","","","")              -> file||80||||file://:80|0     <-- no special schemes
// ("HTTP","EXAMPLE.COM","80","/","","")  -> http|EXAMPLE.COM|80|/|||http://EXAMPLE.COM:80/|1
// ("http","example.com","abc","/","","") -> stdout EMPTY, rc=134, stderr stoi invalid_argument
